  const tbl = (rows, head) => `<table class="tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const FL = M.fluid(); // default simplified model: 35 → 18 mmHg hydrostatic, 25 mmHg oncotic
  const LOWP = M.fluid({ onc: 15 }); // low plasma protein
  const HIGHV = M.fluid({ Pv: 28 }); // raised venous pressure
