  const VD = { artery: { lumen: 4.0, wall: 1.0 }, vein: { lumen: 5.0, wall: 0.5 } };
  const ratio = (v) => VD[v].wall / VD[v].lumen; // wall thickness ÷ lumen diameter
  const totalD = (v) => VD[v].lumen + 2 * VD[v].wall;
  // ILLUSTRATIVE mean pressures along the systemic circulation (typical textbook values, rounded), mmHg
  const PRES = [["Aorta", 95], ["Small arteries", 85], ["Arterioles (start)", 80], ["Capillaries (arteriole end)", 35], ["Capillaries (venule end)", 18], ["Venules", 15], ["Vena cava", 3]];
